"""Migrated validation rules for ACCT_MASTER."""

from typing import Any


def _value(record: dict | None, key: str) -> Any:
    """Return a field value, treating missing and None values as empty strings."""
    if record is None:
        return ""
    value = record.get(key, "")
    return "" if value is None else value


def _numeric(value: Any) -> float:
    """Apply legacy numeric coercion: blank or missing values compare as zero."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image against migrated legacy rules."""
    del today  # Included for the fixed interface; these rules do not use TODAY().

    errors: list[dict] = []

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    # ACC-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(str(_value(record, "ACCT_NM"))) < 2:
            add("E1001", "Account name too short")

    # ACC-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            add("E1002", "Invalid account type")

    # ACC-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        ann_rev = _value(record, "ANN_REV")
        if _numeric(0 if ann_rev == "" else ann_rev) < 0:
            add("E1003", "Annual revenue negative")

    # ACC-004: UPDATE only
    if event == "UPDATE":
        old_cred_hold = _value(old, "CRED_HOLD")
        if (
            old_cred_hold == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _numeric(_value(record, "CRED_LIMIT")) <= 0
        ):
            add("E1004", "Cannot release credit hold with zero credit limit")

    # ACC-005: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(str(_value(record, "REGION_CD"))) != 3:
            add("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
